<script setup>
import { ref, reactive, onMounted } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { auth } from '../lib/auth.js'
import { get, post, put, allPages } from '../lib/http.js'
import { useLoad } from '../lib/useLoad.js'
import { chinaDate, slots, money, dateTime } from '../lib/helpers.js'
import ErrorPanel from '../components/ErrorPanel.vue'
import StatusBadge from '../components/StatusBadge.vue'
import Pager from '../components/Pager.vue'
const route = useRoute(), router = useRouter(), admin = auth.user.role === 'ADMIN'
const filters = reactive({ startDate: route.query.startDate || chinaDate(), endDate: route.query.endDate || chinaDate(6), doctorId: route.query.doctorId || '', departmentId: route.query.departmentId || '', status: route.query.status || '', page:Number(route.query.page) || 1, pageSize:20 })
const departments = ref([]), doctors = ref([]), directoryError = ref(null)
const { data, loading, error, load } = useLoad(() => get(admin ? '/admin/schedules' : '/doctor/schedules', filters))
const modal = ref(false), form = reactive({}), editing = ref(null), saving = ref(false), formError = ref(null), actionError = ref(null), closing = ref(null)
async function directory() { if (!admin) return; directoryError.value = null; try { [departments.value, doctors.value] = await Promise.all([allPages('/admin/departments'), allPages('/admin/doctors')]) } catch(e) { directoryError.value = e } }
async function search(page = 1) { filters.page = page; router.replace({ query: Object.fromEntries(Object.entries(filters).filter(([k,v]) => k !== 'pageSize' && v !== '' && !(k === 'page' && v === 1))) }); await load() }
function open(item = null) { editing.value = item?.id || null; formError.value = null; Object.keys(form).forEach(k => delete form[k]); Object.assign(form, { doctorId:'', visitDate:chinaDate(1), timeSlot:'AM', totalCount:20, fee:20, status:'OPEN', bookingDeadline:null }, item || {}); modal.value = true }
async function save() {
  if (saving.value) return
  formError.value = null
  if (!form.doctorId || !form.visitDate || !form.totalCount || form.fee == null) { formError.value = new Error('请填写医生、日期、号源总量和费用。'); return }
  saving.value = true
  try { const payload = Object.fromEntries(['doctorId','visitDate','timeSlot','totalCount','fee','status','bookingDeadline'].map(k => [k,form[k]])); await (editing.value ? put(`/admin/schedules/${editing.value}`, payload) : post('/admin/schedules', payload)); modal.value = false; ElMessage.success('排班已保存'); await load() } catch(e) { formError.value = e } finally { saving.value = false }
}
async function close(item) {
  try { await ElMessageBox.confirm(`确认关闭 ${item.doctorName} ${item.visitDate} ${slots[item.timeSlot]} 的场次？存在待接诊或接诊中预约时无法关闭。`, '关闭场次', { type:'warning', confirmButtonText:'确认关闭', cancelButtonText:'返回' }) } catch { return }
  closing.value = item.id; actionError.value = null
  try { await post(`/admin/schedules/${item.id}/close`); ElMessage.success('场次已关闭'); await load() } catch(e) { actionError.value = e } finally { closing.value = null }
}
onMounted(() => Promise.all([directory(), load()]))
</script>
<template>
  <div class="page-heading"><div><h1 tabindex="-1">{{ admin ? '排班管理' : '我的排班' }}</h1><p>{{ admin ? '维护号源总量、费用与截止时间；剩余号源由预约占用自动计算。' : '查看本人场次与号源占用情况，排班由管理员维护。' }}</p></div><el-button v-if="admin" type="primary" :disabled="!!directoryError" @click="open()">新增排班</el-button></div>
  <ErrorPanel :error="directoryError" @retry="directory" /><ErrorPanel :error="actionError" />
  <section class="panel"><form class="filter-bar" @submit.prevent="search()"><div><label for="scheduleStart">开始日期</label><el-date-picker id="scheduleStart" v-model="filters.startDate" type="date" value-format="YYYY-MM-DD" :clearable="false" /></div><div><label for="scheduleEnd">结束日期</label><el-date-picker id="scheduleEnd" v-model="filters.endDate" type="date" value-format="YYYY-MM-DD" :clearable="false" /></div><template v-if="admin"><div><label for="scheduleDept">科室</label><el-select id="scheduleDept" v-model="filters.departmentId" clearable placeholder="全部科室"><el-option v-for="d in departments" :key="d.id" :label="d.name" :value="d.id" /></el-select></div><div><label for="scheduleDoctor">医生</label><el-select id="scheduleDoctor" v-model="filters.doctorId" clearable filterable placeholder="全部医生"><el-option v-for="d in doctors" :key="d.id" :label="d.name" :value="d.id" /></el-select></div><div><label for="scheduleStatus">场次状态</label><el-select id="scheduleStatus" v-model="filters.status" placeholder="全部状态"><el-option label="全部状态" value="" /><el-option label="开放" value="OPEN" /><el-option label="关闭" value="CLOSED" /></el-select></div></template><el-button type="primary" native-type="submit" :loading="loading">查询排班</el-button></form>
  <ErrorPanel :error="error" @retry="load" /><div class="table-container"><el-table v-loading="loading" :data="data?.items || []" empty-text="所选日期范围暂无排班" row-key="id"><el-table-column prop="visitDate" label="日期" width="120" /><el-table-column label="时段" min-width="135"><template #default="{ row }">{{ slots[row.timeSlot] }}</template></el-table-column><el-table-column prop="departmentName" label="科室" min-width="140" /><el-table-column v-if="admin" prop="doctorName" label="医生" min-width="120" /><el-table-column prop="totalCount" label="总号源" width="90" /><el-table-column prop="remainingCount" label="剩余" width="85" /><el-table-column label="已占用" width="90"><template #default="{ row }">{{ row.totalCount - row.remainingCount }}</template></el-table-column><el-table-column label="费用" width="100"><template #default="{ row }">{{ money(row.fee) }}</template></el-table-column><el-table-column label="预约截止" min-width="165"><template #default="{ row }">{{ dateTime(row.bookingDeadline) }}</template></el-table-column><el-table-column label="状态" width="95"><template #default="{ row }"><StatusBadge :status="row.status" /></template></el-table-column><el-table-column v-if="admin" label="操作" width="175"><template #default="{ row }"><el-button size="small" :disabled="!!directoryError" @click="open(row)">编辑</el-button><el-button size="small" type="danger" plain :disabled="row.status === 'CLOSED'" :loading="closing === row.id" @click="close(row)">关闭</el-button></template></el-table-column></el-table></div><Pager :page="filters.page" :total="data?.total || 0" @change="search" /></section>
  <el-dialog v-model="modal" :title="editing ? '编辑排班' : '新增排班'" width="600px" :close-on-click-modal="false" :close-on-press-escape="!saving" :show-close="!saving" :before-close="done => { if (!saving) done() }"><ErrorPanel :error="formError" /><form id="scheduleForm" @submit.prevent="save"><label for="editScheduleDoctor">医生 <span class="required">*</span></label><el-select id="editScheduleDoctor" v-model="form.doctorId" filterable :disabled="!!editing" placeholder="请选择医生"><el-option v-for="d in doctors" :key="d.id" :label="`${d.name} · ${departments.find(v => v.id === d.departmentId)?.name || '未知科室'}`" :value="d.id" :disabled="d.status !== 'ENABLED' && d.id !== form.doctorId" /></el-select><div class="form-grid"><div><label for="editScheduleDate">就诊日期 <span class="required">*</span></label><el-date-picker id="editScheduleDate" v-model="form.visitDate" type="date" value-format="YYYY-MM-DD" :clearable="false" :disabled="!!editing" /></div><div><label for="editScheduleSlot">就诊时段</label><el-select id="editScheduleSlot" v-model="form.timeSlot" :disabled="!!editing"><el-option label="上午 · 08:00" value="AM" /><el-option label="下午 · 14:00" value="PM" /></el-select></div><div><label for="editScheduleTotal">号源总量 <span class="required">*</span></label><el-input-number id="editScheduleTotal" v-model="form.totalCount" :min="1" :max="100000" :precision="0" controls-position="right" /></div><div><label for="editScheduleFee">挂号费用（元）</label><el-input-number id="editScheduleFee" v-model="form.fee" :min="0" :max="99999999.99" :precision="2" controls-position="right" /></div></div><label for="editScheduleDeadline">预约 / 取消截止（北京时间）</label><el-date-picker id="editScheduleDeadline" v-model="form.bookingDeadline" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" placeholder="不填则为场次开始前 30 分钟" /><label for="editScheduleStatus">状态</label><el-select id="editScheduleStatus" v-model="form.status"><el-option label="开放" value="OPEN" /><el-option label="关闭" value="CLOSED" /></el-select><p v-if="editing" class="muted">编辑时保留医生、日期与时段；剩余号源按实际占用重算，历史预约费用保持原值。</p></form><template #footer><el-button :disabled="saving" @click="modal = false">返回</el-button><el-button type="primary" native-type="submit" form="scheduleForm" :loading="saving">保存排班</el-button></template></el-dialog>
</template>
